Use Convex 1.44.0. The teams schema has adminId: v.id("users"). A team T references user U. A completed mutation physically deletes U but makes no explicit change to T. No other writes occur. The query below is then called with T's ID.

```ts
import { query } from "./_generated/server";
import { v } from "convex/values";
import { paginationOptsValidator, paginationResultValidator } from "convex/server";
export const candidate = query({
  args: { teamId: v.id("teams") },
  handler: async (ctx, args) => {
    const team = await ctx.db.get("teams", args.teamId);
    if (team === null) return { teamExists: false, admin: null };
    const admin = await ctx.db.get("users", team.adminId);
    return { teamExists: true, admin };
  },
});
```
